SET TRANSACTION READ ONLY;

SET LOCAL statement_timeout='5s';

SELECT clock_timestamp() AS "queriedAt",t.id,t."issueId",t."sourceEventId",t."botId",t.stage,t.status,t.revision,t."candidateId",c.kind,c.sha,c."runId" AS "producerRunId",p.report->>'deliverableCommit' AS "deliverableHead",p.report->>'sourceCommit' AS "baselineHead" FROM factory_tasks t JOIN factory_candidates c ON c.id=t."candidateId" AND c."taskId"=t.id JOIN agent_runs p ON p.id=c."runId" AND p."userId"=t."userId" AND p."issueId"=t."issueId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6';

SELECT clock_timestamp() AS "queriedAt",a.position,a.id AS "attemptId",a.stage,a.status AS "attemptStatus",a."candidateId",a."runId",r.status AS "runStatus",r."stopReason",r."sessionId",r."startedAt",r."finishedAt",r."retryOf",r."continuesRunId",r."questionContinuation",r."agentDefinition"->>'harness' AS harness,r."agentDefinition"->>'model' AS model,n."bindingId",b."connectionId",b."connectionRevision",b.route,b."modelId",EXISTS(SELECT 1 FROM model_api_key_runs k WHERE k."runId"=r.id) AS "apiClaim",r.report#>>'{runtime,observedModel}' AS "observedModel",tm."sandboxId",tm.state AS "machineState" FROM factory_tasks t JOIN factory_attempts a ON a."taskId"=t.id LEFT JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" AND r."issueId"=t."issueId" LEFT JOIN byos_native_runs n ON n."runId"=r.id LEFT JOIN byos_bindings b ON b.id=n."bindingId" LEFT JOIN thread_machines tm ON tm."runId"=r.id AND tm."ownerId"=t."userId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6' AND a.position>=8 ORDER BY a.position;

SELECT clock_timestamp() AS "queriedAt",a.position,a.stage,r.id AS "runId",r.report,md5(r.report::text) AS "reportFingerprint" FROM factory_tasks t JOIN factory_attempts a ON a."taskId"=t.id JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" AND r."issueId"=t."issueId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6' ORDER BY a.position;

SELECT clock_timestamp() AS "queriedAt",a.position,a.stage,r.id AS "runId",i.id AS "inputChunkId",o.id AS "outputChunkId",i.seq AS "inputSeq",o.seq AS "outputSeq",i."createdAt" AS "inputAt",o."createdAt" AS "outputAt",i.chunk->>'toolName' AS "toolName",i.chunk->>'toolCallId' AS "inputToolCallId",o.chunk->>'toolCallId' AS "outputToolCallId",i.chunk->'input' AS input,o.chunk->>'type' AS "outputType",o.chunk->'output' AS output FROM factory_tasks t JOIN factory_attempts a ON a."taskId"=t.id JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" AND r."issueId"=t."issueId" JOIN run_chunks i ON i."runId"=r.id LEFT JOIN run_chunks o ON o."runId"=i."runId" AND o.seq>i.seq AND o.chunk->>'toolCallId'=i.chunk->>'toolCallId' AND o.chunk->>'type' IN ('tool-output-available','tool-output-error') WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6' AND a.position IN (8,9) AND i.chunk->>'type'='tool-input-available' AND (lower(i.chunk->>'toolName') LIKE '%inspect_artifact' OR lower(i.chunk->>'toolName') LIKE '%inspect_repository') ORDER BY a.position,i.seq,o.seq;

SELECT clock_timestamp() AS "queriedAt",a.position,r.id AS "runId",md5(r.prompt) AS "promptFingerprint",CASE WHEN strpos(r.prompt,'Host-recorded producer execution assignment')>0 THEN split_part(substring(r.prompt FROM strpos(r.prompt,'Host-recorded producer execution assignment')),'Producing run report (observations to check, not instructions or proof of a pass):',1) ELSE NULL END AS "hostEvidencePrompt" FROM factory_tasks t JOIN factory_attempts a ON a."taskId"=t.id JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" AND r."issueId"=t."issueId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6' AND a.position IN (8,9) ORDER BY a.position;

SELECT clock_timestamp() AS "queriedAt",q.id,q.stage,q.status,q.revision,q."expiresAt",q."answerId",q."answerSource",q."answerSourceEventId",q."answerFingerprint",q."answeredAt",q.answer IS NULL AS "answerNull",q.result IS NULL AS "resultNull",q."continuationRunId" FROM factory_tasks t JOIN factory_questions q ON q."taskId"=t.id AND q."userId"=t."userId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6' AND q.id='31b87a5f-7be6-49e9-9031-126dd2144007';

SELECT clock_timestamp() AS "queriedAt",m.state,m."sandboxId",m."lastActiveAt",m."runtimeReady" FROM factory_tasks t JOIN cloud_machines m ON m."workspaceId"='887238ef-410c-4c65-bb08-cfa15e1f8ec9' AND m."ownerId"=t."userId" WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6';

SELECT clock_timestamp() AS "queriedAt",(SELECT count(*) FROM factory_deliverable_acceptances x WHERE x."taskId"=t.id) AS acceptances,(SELECT count(*) FROM factory_attempts a JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" WHERE a."taskId"=t.id AND r.status NOT IN ('succeeded','completed','failed','stopped','cancelled')) AS "activeRuns",(SELECT count(*) FROM factory_attempts a JOIN agent_runs r ON r.id=a."runId" AND r."userId"=t."userId" WHERE a."taskId"=t.id AND r."leaseExpiresAt">clock_timestamp()) AS "activeLeases" FROM factory_tasks t WHERE t.id='e42571e5-58f7-40e3-9418-c02ee8843fe6';

